/**
 * What the MHPCO reimburses for reported damage: the damage amount, less the
 * deductible that applies per damage event.
 *
 * This is the one place that says how much an incident is worth to the
 * claimant. How far the MHPCO will actually go in paying that -- what the
 * policy's cap leaves of it -- is a separate decision, made where the policy
 * settles the claim.
 */
public final class Reimbursement {

    private static final int DEDUCTIBLE_PER_DAMAGE_IN_G = 100;

    private Reimbursement() {
    }

    /**
     * An incident is reimbursed damage by damage: the office settles each
     * reported damage on its own and pays the sum, because the deductible is
     * charged per damage event rather than once for the incident.
     */
    public static int forIncident(Incident incident) {
        return incident.damages().stream()
                .mapToInt(Reimbursement::forDamage)
                .sum();
    }

    private static int forDamage(Damage damage) {
        return damage.amount() - DEDUCTIBLE_PER_DAMAGE_IN_G;
    }
}
--- src/main/java/PayoutCap.java
/**
 * The most the MHPCO will pay out over the life of a policy: twice the
 * insurance sum of the items it covers.
 *
 * This is the one place that decides the office's payout ceiling. It is a
 * separate decision from what the covered items are insured for: the MHPCO may
 * revalue the items it covers without changing how far it will go beyond that
 * value, and may change how far it will go without revaluing anything.
 */
public final class PayoutCap {

    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

    private PayoutCap() {
    }

    public static int overInsuranceSum(int insuranceSumInG) {
        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumInG;
    }
}
